/**
 * Data access for Machine Learning — Zero to Professional.
 *
 * Loader only: the artifact is generated by `scripts/ml-course.cjs` from
 * `content/ml-mastery/`, and every progress rule lives in `core/learning/mcourse.ts`.
 */
import { useEffect, useState } from 'react';
import type { NCourseFile } from '../learning/ncourse';

let cached: Promise<NCourseFile> | null = null;

function load(): Promise<NCourseFile> {
  if (!cached) {
    cached = fetch('generated/ml-course/index.json')
      .then((response) => {
        if (!response.ok) throw new Error(`ml-course/index.json: ${response.status}`);
        return response.json() as Promise<NCourseFile>;
      })
      .catch((error) => { cached = null; throw error; });
  }
  return cached;
}

export function useMLCourse(): NCourseFile | null {
  const [data, setData] = useState<NCourseFile | null>(null);
  useEffect(() => {
    let live = true;
    load().then((course) => { if (live) setData(course); }).catch(() => { /* the page shows its loading state */ });
    return () => { live = false; };
  }, []);
  return data;
}
